import os
import numpy as np


def safe_get(d, *keys, default=None):
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return default
    return cur


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    path = os.path.join(working_dir, "experiment_data.npy")
    if not os.path.isfile(path):
        raise FileNotFoundError(f"File not found: {path}")
    data = np.load(path, allow_pickle=True).item()
    if not isinstance(data, dict):
        raise ValueError("Loaded experiment_data is not a dict.")
    return data


def extract_final_train_metrics(ds_data):
    # Expect a 'final' entry
    train_entries = safe_get(ds_data, "metrics", "train", default=[])
    final = None
    for tag, vals in train_entries:
        if tag == "final":
            final = vals
    out = {}
    if final:
        out["train loss"] = final.get("loss", None)
        out["train accuracy"] = final.get("acc", None)
        out["train F1 score"] = final.get("macro_f1", None)
        out["train top-3 accuracy"] = final.get("top3", None)
    else:
        # Fallback: try last value from losses for loss only
        train_losses = safe_get(ds_data, "losses", "train", default=[])
        if train_losses:
            out["train loss"] = train_losses[-1][1]
    return out


def extract_best_val_metrics(ds_data):
    # Collect per-epoch validation metrics (acc, macro_f1, top3)
    val_entries = safe_get(ds_data, "metrics", "val", default=[])
    best = {
        "validation accuracy": None,
        "validation F1 score": None,
        "validation top-3 accuracy": None,
    }
    for tag, vals in val_entries:
        if isinstance(vals, dict):
            acc = vals.get("acc", None)
            f1 = vals.get("macro_f1", None)
            top3 = vals.get("top3", None)
            if acc is not None:
                best["validation accuracy"] = (
                    acc
                    if best["validation accuracy"] is None
                    else max(best["validation accuracy"], acc)
                )
            if f1 is not None:
                best["validation F1 score"] = (
                    f1
                    if best["validation F1 score"] is None
                    else max(best["validation F1 score"], f1)
                )
            if top3 is not None:
                best["validation top-3 accuracy"] = (
                    top3
                    if best["validation top-3 accuracy"] is None
                    else max(best["validation top-3 accuracy"], top3)
                )
    # For validation loss, use recorded losses per epoch and take the minimum
    val_losses = safe_get(ds_data, "losses", "val", default=[])
    if val_losses:
        min_val_loss = min((v for (_, v) in val_losses), default=None)
    else:
        # fallback: check 'final' val entry if present
        min_val_loss = None
        for tag, vals in val_entries:
            if tag == "final" and isinstance(vals, dict):
                min_val_loss = vals.get("loss", None)
                break
    out = {"validation loss": min_val_loss}
    out.update(best)
    return out


def extract_final_test_metrics(ds_data):
    test_entries = safe_get(ds_data, "metrics", "test", default=[])
    final = None
    for tag, vals in test_entries:
        if tag == "final":
            final = vals
    out = {}
    if final:
        out["test loss"] = final.get("loss", None)
        out["test accuracy"] = final.get("acc", None)
        out["test F1 score"] = final.get("macro_f1", None)
        out["test top-3 accuracy"] = final.get("top3", None)
    return out


def format_print_metrics(dataset_name, metrics_dict):
    print(dataset_name)
    # Keep a consistent order for readability
    ordered_keys = [
        "train loss",
        "train accuracy",
        "train F1 score",
        "train top-3 accuracy",
        "validation loss",
        "validation accuracy",
        "validation F1 score",
        "validation top-3 accuracy",
        "test loss",
        "test accuracy",
        "test F1 score",
        "test top-3 accuracy",
    ]
    printed_any = False
    for k in ordered_keys:
        if k in metrics_dict and metrics_dict[k] is not None:
            val = metrics_dict[k]
            if isinstance(val, float):
                print(f"{k}: {val:.4f}")
            else:
                print(f"{k}: {val}")
            printed_any = True
    # Print any remaining keys that were not in the ordered list
    for k, v in metrics_dict.items():
        if k not in ordered_keys and v is not None:
            if isinstance(v, float):
                print(f"{k}: {v:.4f}")
            else:
                print(f"{k}: {v}")
            printed_any = True
    if not printed_any:
        print("No metrics available")


def run():
    experiment_data = load_experiment_data()
    for ds_name, ds_data in experiment_data.items():
        all_metrics = {}
        all_metrics.update(extract_final_train_metrics(ds_data))
        all_metrics.update(extract_best_val_metrics(ds_data))
        all_metrics.update(extract_final_test_metrics(ds_data))
        format_print_metrics(ds_name, all_metrics)


# Execute immediately
run()

import os
import numpy as np


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    npy_path = os.path.join(working_dir, "experiment_data.npy")
    npz_path = os.path.join(working_dir, "experiment_data_compressed.npz")

    data = None
    if os.path.isfile(npy_path):
        data = np.load(npy_path, allow_pickle=True).item()
    elif os.path.isfile(npz_path):
        # Fallback if only compressed exists
        z = np.load(npz_path, allow_pickle=True)
        if "data" in z.files:
            data = z["data"].item()
    if data is None:
        raise FileNotFoundError(
            "Could not find experiment_data.npy or experiment_data_compressed.npz in working directory."
        )
    return data


def get_final_entry(metric_list):
    # metric_list contains tuples like (epoch, dict) and also ('final', dict)
    if not isinstance(metric_list, list):
        return None
    final_entries = [
        entry
        for entry in metric_list
        if isinstance(entry, tuple) and entry and entry[0] == "final"
    ]
    if final_entries:
        # Return the last 'final' entry
        return final_entries[-1][1]
    # If no final, try last epoch entry
    epoch_entries = [
        entry
        for entry in metric_list
        if isinstance(entry, tuple) and isinstance(entry[0], (int, np.integer))
    ]
    if epoch_entries:
        return epoch_entries[-1][1]
    return None


def print_metrics_for_dataset(name, dct):
    # dct structure:
    # dct["metrics"]["train"] list: has a ("final", {...})
    # dct["metrics"]["val"] list: per-epoch (epoch, {...}) and a ("final", {...})
    # dct["metrics"]["test"] list: a ("final", {...})
    print(name)

    metrics = dct.get("metrics", {})
    train_final = get_final_entry(metrics.get("train", []))
    val_final = get_final_entry(metrics.get("val", []))
    test_final = get_final_entry(metrics.get("test", []))

    def fmt(v):
        if isinstance(v, (float, np.floating)):
            return f"{float(v):.4f}"
        return str(v)

    # Train metrics
    if isinstance(train_final, dict):
        if "loss" in train_final:
            print(f"train loss: {fmt(train_final['loss'])}")
        if "acc" in train_final:
            print(f"train accuracy: {fmt(train_final['acc'])}")
        if "macro_f1" in train_final:
            print(f"train F1 score (macro): {fmt(train_final['macro_f1'])}")
        if "top3" in train_final:
            print(f"train top-3 accuracy: {fmt(train_final['top3'])}")

    # Validation metrics
    if isinstance(val_final, dict):
        if "loss" in val_final:
            print(f"validation loss: {fmt(val_final['loss'])}")
        if "acc" in val_final:
            print(f"validation accuracy: {fmt(val_final['acc'])}")
        if "macro_f1" in val_final:
            print(f"validation F1 score (macro): {fmt(val_final['macro_f1'])}")
        if "top3" in val_final:
            print(f"validation top-3 accuracy: {fmt(val_final['top3'])}")
        # workload metric
        if "wMAPE@H" in val_final:
            print(f"validation wMAPE@H: {fmt(val_final['wMAPE@H'])}")

    # Test metrics
    if isinstance(test_final, dict):
        if "loss" in test_final:
            print(f"test loss: {fmt(test_final['loss'])}")
        if "acc" in test_final:
            print(f"test accuracy: {fmt(test_final['acc'])}")
        if "macro_f1" in test_final:
            print(f"test F1 score (macro): {fmt(test_final['macro_f1'])}")
        if "top3" in test_final:
            print(f"test top-3 accuracy: {fmt(test_final['top3'])}")
        # workload metric
        if "wMAPE@H" in test_final:
            print(f"test wMAPE@H: {fmt(test_final['wMAPE@H'])}")


def run():
    experiment_data = load_experiment_data()
    # Iterate datasets
    for dataset_name, dataset_dict in experiment_data.items():
        try:
            print_metrics_for_dataset(dataset_name, dataset_dict)
        except Exception as e:
            print(dataset_name)
            print(f"error: {e}")


# Execute immediately
run()

import os
import numpy as np


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    path = os.path.join(working_dir, "experiment_data.npy")
    if not os.path.exists(path):
        raise FileNotFoundError(f"experiment_data.npy not found at {path}")
    data = np.load(path, allow_pickle=True).item()
    return data


def get_final_metric(metrics_list, key):
    # metrics_list entries are tuples: (tag, dict)
    # We look for the entry with tag == "final" and return dict[key] if exists
    for tag, d in metrics_list:
        if tag == "final" and key in d:
            return d[key]
    return None


def get_best_val_metrics(exp_entry):
    # Best validation loss from losses["val"] (min)
    best_val_loss = None
    for ep, vloss in exp_entry.get("losses", {}).get("val", []):
        if best_val_loss is None or vloss < best_val_loss:
            best_val_loss = vloss

    # Best validation metrics across epochs from metrics["val"] entries with integer epoch tags
    best_val_acc = None
    best_val_f1 = None
    best_val_top3 = None
    # For wMAPE@H lower is better
    best_val_wmape = None

    for tag, d in exp_entry.get("metrics", {}).get("val", []):
        if isinstance(tag, int):
            if "acc" in d:
                if best_val_acc is None or d["acc"] > best_val_acc:
                    best_val_acc = d["acc"]
            if "macro_f1" in d:
                if best_val_f1 is None or d["macro_f1"] > best_val_f1:
                    best_val_f1 = d["macro_f1"]
            if "top3" in d:
                if best_val_top3 is None or d["top3"] > best_val_top3:
                    best_val_top3 = d["top3"]
            if "wMAPE@H" in d:
                if best_val_wmape is None or d["wMAPE@H"] < best_val_wmape:
                    best_val_wmape = d["wMAPE@H"]

    return best_val_loss, best_val_acc, best_val_f1, best_val_top3, best_val_wmape


def print_metrics(exp_data):
    for dataset_name, entry in exp_data.items():
        print(dataset_name)

        # Train final metrics
        train_metrics = entry.get("metrics", {}).get("train", [])
        train_loss = get_final_metric(train_metrics, "loss")
        train_acc = get_final_metric(train_metrics, "acc")
        train_f1 = get_final_metric(train_metrics, "macro_f1")
        train_top3 = get_final_metric(train_metrics, "top3")

        if train_loss is not None:
            print(f"- train loss: {train_loss:.6f}")
        if train_acc is not None:
            print(f"- train accuracy: {train_acc:.6f}")
        if train_f1 is not None:
            print(f"- train macro F1 score: {train_f1:.6f}")
        if train_top3 is not None:
            print(f"- train top-3 accuracy: {train_top3:.6f}")

        # Best validation metrics
        best_val_loss, best_val_acc, best_val_f1, best_val_top3, best_val_wmape = (
            get_best_val_metrics(entry)
        )
        if best_val_loss is not None:
            print(f"- best validation loss: {best_val_loss:.6f}")
        if best_val_acc is not None:
            print(f"- best validation accuracy: {best_val_acc:.6f}")
        if best_val_f1 is not None:
            print(f"- best validation macro F1 score: {best_val_f1:.6f}")
        if best_val_top3 is not None:
            print(f"- best validation top-3 accuracy: {best_val_top3:.6f}")
        if best_val_wmape is not None and not (
            isinstance(best_val_wmape, float) and (np.isnan(best_val_wmape))
        ):
            print(f"- best validation workload wMAPE@H: {best_val_wmape:.6f}")

        # Test final metrics
        test_metrics = entry.get("metrics", {}).get("test", [])
        test_loss = get_final_metric(test_metrics, "loss")
        test_acc = get_final_metric(test_metrics, "acc")
        test_f1 = get_final_metric(test_metrics, "macro_f1")
        test_top3 = get_final_metric(test_metrics, "top3")
        test_wmape = get_final_metric(test_metrics, "wMAPE@H")

        if test_loss is not None:
            print(f"- test loss: {test_loss:.6f}")
        if test_acc is not None:
            print(f"- test accuracy: {test_acc:.6f}")
        if test_f1 is not None:
            print(f"- test macro F1 score: {test_f1:.6f}")
        if test_top3 is not None:
            print(f"- test top-3 accuracy: {test_top3:.6f}")
        if test_wmape is not None and not (
            isinstance(test_wmape, float) and (np.isnan(test_wmape))
        ):
            print(f"- test workload wMAPE@H: {test_wmape:.6f}")


def main():
    exp_data = load_experiment_data()
    print_metrics(exp_data)


