import os
import numpy as np


def load_experiment(path):
    return np.load(path, allow_pickle=True).item()


def find_final(metrics_list):
    # metrics_list is a list of tuples; final entry looks like ("final", dict)
    for k, v in metrics_list:
        if k == "final":
            return v
    return None


def extract_val_wmape_best(val_metrics):
    # val_metrics contains (epoch, dict) for epochs and a ("final", dict) at the end
    # wMAPE is only tracked during epochs under a key like "wMAPE@60"
    best = None
    best_key = None
    for k, v in val_metrics:
        if isinstance(k, (int, np.integer)) and isinstance(v, dict):
            # find any key that starts with "wMAPE@"
            for mk, mv in v.items():
                if isinstance(mk, str) and mk.startswith("wMAPE@"):
                    # lower is better
                    if mv is not None and not (
                        isinstance(mv, float) and (np.isnan(mv))
                    ):
                        if best is None or mv < best:
                            best = mv
                            best_key = mk
    return best_key, best


def print_metrics(exp_data):
    for dataset_name, content in exp_data.items():
        print(dataset_name)

        metrics = content.get("metrics", {})
        train_list = metrics.get("train", [])
        val_list = metrics.get("val", [])
        test_list = metrics.get("test", [])

        # Train final
        train_final = find_final(train_list) or {}
        if train_final:
            if "loss" in train_final:
                print(f"train loss: {train_final['loss']:.4f}")
            if "acc" in train_final:
                print(f"train accuracy: {train_final['acc']:.4f}")
            if "macro_f1" in train_final:
                print(f"train F1 score (macro): {train_final['macro_f1']:.4f}")
            if "top3" in train_final:
                print(f"train top-3 accuracy: {train_final['top3']:.4f}")

        # Validation final
        val_final = find_final(val_list) or {}
        if val_final:
            if "loss" in val_final:
                print(f"validation loss: {val_final['loss']:.4f}")
            if "acc" in val_final:
                print(f"validation accuracy: {val_final['acc']:.4f}")
            if "macro_f1" in val_final:
                print(f"validation F1 score (macro): {val_final['macro_f1']:.4f}")
            if "top3" in val_final:
                print(f"validation top-3 accuracy: {val_final['top3']:.4f}")

        # Validation best wMAPE across epochs (if available)
        wmape_key, wmape_best = extract_val_wmape_best(val_list)
        if wmape_key is not None and wmape_best is not None:
            # Normalize label like "wMAPE@60" -> "validation wMAPE@60"
            print(f"validation {wmape_key}: {wmape_best:.4f}")

        # Test final
        test_final = find_final(test_list) or {}
        if test_final:
            if "loss" in test_final:
                print(f"test loss: {test_final['loss']:.4f}")
            if "acc" in test_final:
                print(f"test accuracy: {test_final['acc']:.4f}")
            if "macro_f1" in test_final:
                print(f"test F1 score (macro): {test_final['macro_f1']:.4f}")
            if "top3" in test_final:
                print(f"test top-3 accuracy: {test_final['top3']:.4f}")
            # Print any test wMAPE key if present (e.g., 'wMAPE@60')
            for mk, mv in test_final.items():
                if isinstance(mk, str) and mk.startswith("wMAPE@"):
                    print(f"test {mk}: {mv:.4f}")


