import os
import numpy as np


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    path = os.path.join(working_dir, "experiment_data.npy")
    data = np.load(path, allow_pickle=True).item()
    return data


def safe_get(dct, key, default=None):
    try:
        return dct.get(key, default)
    except Exception:
        return default


def extract_final_metrics(section_list):
    # section_list contains tuples like ('final', {dict})
    final = None
    for tag, payload in section_list:
        if tag == "final":
            final = payload
    return final or {}


def best_from_val_metrics(val_metrics_list, val_losses_list, val_wmape_list):
    # val_metrics_list: list of (tag_or_epoch, dict{acc, macro_f1, top3, wMAPE_H?})
    # val_losses_list: list of (epoch, loss)
    # val_wmape_list: list of (epoch, value_or_None)
    # Aggregate candidates
    acc_vals = []
    f1_vals = []
    top3_vals = []
    # Per-epoch entries do not include loss; loss is tracked separately
    for tag, md in val_metrics_list:
        if not isinstance(md, dict):
            continue
        if "acc" in md and md["acc"] is not None:
            acc_vals.append(float(md["acc"]))
        if "macro_f1" in md and md["macro_f1"] is not None:
            f1_vals.append(float(md["macro_f1"]))
        if "top3" in md and md["top3"] is not None:
            top3_vals.append(float(md["top3"]))

    # Include 'final' validation metrics as candidates as well (already included above)
    best = {}
    if acc_vals:
        best["validation accuracy"] = max(acc_vals)
    if f1_vals:
        best["validation F1 score"] = max(f1_vals)
    if top3_vals:
        best["validation top-3 accuracy"] = max(top3_vals)

    # Best validation loss: from val_losses_list and possibly 'final' val metric loss
    loss_candidates = []
    for ep, ls in val_losses_list:
        try:
            loss_candidates.append(float(ls))
        except Exception:
            pass
    # also scan for any 'loss' present in val_metrics_list payloads
    for tag, md in val_metrics_list:
        if isinstance(md, dict) and "loss" in md and md["loss"] is not None:
            try:
                loss_candidates.append(float(md["loss"]))
            except Exception:
                pass
    if loss_candidates:
        best["validation loss"] = min(loss_candidates)

    # Best validation wMAPE@H (lower is better)
    wmape_candidates = []
    for ep, v in val_wmape_list:
        if v is None:
            continue
        try:
            wmape_candidates.append(float(v))
        except Exception:
            pass
    # It might also appear in val_metrics_list dicts as 'wMAPE_H'
    for tag, md in val_metrics_list:
        if isinstance(md, dict) and "wMAPE_H" in md and md["wMAPE_H"] is not None:
            try:
                wmape_candidates.append(float(md["wMAPE_H"]))
            except Exception:
                pass
    if wmape_candidates:
        best["validation wMAPE@H"] = min(wmape_candidates)

    return best


def print_dataset_metrics(name, ed):
    # ed structure per dataset based on training script
    metrics = safe_get(ed, "metrics", {"train": [], "val": [], "test": []})
    losses = safe_get(ed, "losses", {"train": [], "val": []})
    wmape_H = safe_get(ed, "wMAPE_H", {"val": [], "test": None})

    train_final = extract_final_metrics(safe_get(metrics, "train", []))
    val_list = safe_get(metrics, "val", [])
    test_final = extract_final_metrics(safe_get(metrics, "test", []))

    train_losses_list = safe_get(losses, "train", [])
    val_losses_list = safe_get(losses, "val", [])

    val_wmape_list = safe_get(wmape_H, "val", [])
    test_wmape = safe_get(wmape_H, "test", None)

    # Print dataset name
    print(name)

    # Train: print final metrics if available
    if "loss" in train_final:
        print(f"train loss: {float(train_final['loss'])}")
    # Also fallback to last train loss from losses list if 'loss' missing
    elif train_losses_list:
        try:
            print(f"train loss: {float(train_losses_list[-1][1])}")
        except Exception:
            pass
    if "acc" in train_final:
        print(f"train accuracy: {float(train_final['acc'])}")
    if "macro_f1" in train_final:
        print(f"train F1 score: {float(train_final['macro_f1'])}")
    if "top3" in train_final:
        print(f"train top-3 accuracy: {float(train_final['top3'])}")

    # Validation: best metrics
    best_val = best_from_val_metrics(val_list, val_losses_list, val_wmape_list)
    for key in [
        "validation loss",
        "validation accuracy",
        "validation F1 score",
        "validation top-3 accuracy",
        "validation wMAPE@H",
    ]:
        if key in best_val:
            print(f"{key}: {best_val[key]}")

    # Test: final metrics and wMAPE@H
    if "loss" in test_final:
        print(f"test loss: {float(test_final['loss'])}")
    if "acc" in test_final:
        print(f"test accuracy: {float(test_final['acc'])}")
    if "macro_f1" in test_final:
        print(f"test F1 score: {float(test_final['macro_f1'])}")
    if "top3" in test_final:
        print(f"test top-3 accuracy: {float(test_final['top3'])}")
    if test_wmape is not None:
        print(f"test wMAPE@H: {float(test_wmape)}")


def main():
    experiment_data = load_experiment_data()
    # Iterate datasets and print metrics
    for name, ed in experiment_data.items():
        print_dataset_metrics(name, ed)


# Execute immediately
main()

import os
import numpy as np


def load_experiment_data():
    working_dir = os.path.join(os.getcwd(), "working")
    path = os.path.join(working_dir, "experiment_data.npy")
    if not os.path.exists(path):
        raise FileNotFoundError(f"experiment_data.npy not found at: {path}")
