    return out


def get_best_validation_metrics(dataset_dict):
    # losses["val"] holds per-epoch tuples (epoch, loss)
    # metrics["val"] holds per-epoch tuples (epoch, {acc, macro_f1, top3, wMAPE@H}) and also ('final', {...})
    best = {}

    # Best validation loss (min over epochs)
    val_losses = dataset_dict.get("losses", {}).get("val", [])
    if val_losses:
        best_val_loss = None
        for ep, loss in val_losses:
            if loss is None:
                continue
            if best_val_loss is None or loss < best_val_loss:
                best_val_loss = loss
        if best_val_loss is not None:
            best["validation loss"] = best_val_loss

    # Best validation metrics: maximize accuracy, macro_f1, top3; minimize wMAPE@H
    val_metrics = dataset_dict.get("metrics", {}).get("val", [])
    best_acc = None
    best_f1 = None
    best_top3 = None
    best_wmape = None

